gaeX(){return"\u062d\u0635\u0631 \u0627\u0644\u0645\u0648\u0638\u0641 \u0641\u064a \u062a\u0635\u0646\u064a\u0641\u0627\u062a \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062d\u0627\u0644\u0627\u062a"},
gaeW(){return"\u0627\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u064b\u0627 \u0644\u0644\u0648\u0635\u0648\u0644 \u0627\u0644\u0643\u0627\u0645\u0644. \u0627\u062e\u062a\u0631 \u062a\u0635\u0646\u064a\u0641\u064b\u0627 \u0623\u0648 \u0623\u0643\u062b\u0631 \u0648\u0633\u064a\u0631\u0649 \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0638\u0641 \u0648\u064a\u0639\u0645\u0644 \u0641\u0642\u0637 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062a\u0627\u0628\u0639\u0629 \u0644\u0647\u0627 \u0641\u064a \u0643\u0644 \u0623\u062c\u0632\u0627\u0621 \u0627\u0644\u062a\u0637\u0628\u064a\u0642. \u0627\u0644\u0645\u062f\u064a\u0631 \u0644\u0627 \u064a\u062a\u0623\u062b\u0631 \u0628\u0647\u0630\u0627 \u0627\u0644\u062d\u0635\u0631. \u0644\u0627 \u062a\u0645\u0646\u062d \u0627\u0644\u0645\u0648\u0638\u0641 \u0627\u0644\u0645\u062d\u0635\u0648\u0631 \u0635\u0644\u0627\u062d\u064a\u0629 \u0627\u0644\u0645\u062f\u0641\u0648\u0639\u0627\u062a \u0623\u0648 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631\u060c \u0641\u0633\u062a\u0634\u0645\u0644 \u0623\u0631\u0642\u0627\u0645\u0647 \u0647\u0630\u0647 \u0627\u0644\u062a\u0635\u0646\u064a\u0641\u0627\u062a \u0641\u0642\u0637."},
QE(a,b){return"\u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u0629: "+a+" \u0645\u0646 "+b+" \u063a\u064a\u063a\u0627\u0628\u0627\u064a\u062a \u0645\u062c\u0627\u0646\u064a\u0629"},
QD(a,b,c){return""+a+" \u063a\u064a\u063a\u0627\u0628\u0627\u064a\u062a \u0645\u0634\u0645\u0648\u0644\u0629. \u0628\u0639\u062f\u0647\u0627 "+b+" \u0644\u0643\u0644 100 \u063a\u064a\u063a\u0627\u0628\u0627\u064a\u062a \u0633\u0646\u0648\u064a\u0627\u064b\u060c \u062d\u0633\u0628 \u0645\u062a\u0648\u0633\u0637 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0643 \u062e\u0644\u0627\u0644 \u0622\u062e\u0631 12 \u0634\u0647\u0631\u0627\u064b ("+c+" \u062d\u0627\u0644\u064a\u0627\u064b)."},
QC(a){return"\u0631\u0633\u0648\u0645 \u0627\u0644\u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u0645\u062a\u0648\u0642\u0639\u0629 \u0647\u0630\u0647 \u0627\u0644\u0633\u0646\u0629: "+a},
ga_j(){return"\u0625\u0631\u0633\u0627\u0644"},
a_k(a){return"\u0623\u064f\u0631\u0633\u0644\u062a "+a},
ga_h(){return"\u0625\u0631\u0633\u0627\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649\u061f"},
H8(a,b){return"\u0623\u064f\u0631\u0633\u0644\u062a \u0647\u0630\u0647 \u0627\u0644\u062d\u0627\u0644\u0629 \u0625\u0644\u0649 "+a+" \u0641\u064a "+b+". \u0647\u0644 \u062a\u0631\u064a\u062f \u0625\u0631\u0633\u0627\u0644\u0647\u0627 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649\u061f"},
ga_g(){return"\u0625\u0631\u0633\u0627\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649"},
gZT(){return"\u0625\u0631\u0633\u0627\u0644 \u0625\u0644\u0649"},
a_l(a){return"\u0623\u064f\u0631\u0633\u0644\u062a \u0625\u0644\u0649 "+a},
a_i(a){return"\u062a\u0639\u0630\u0651\u0631 \u0627\u0644\u0625\u0631\u0633\u0627\u0644: "+a},
gaiK(){return"\u062c\u0647\u0627\u062a \u0627\u0644\u0627\u062a\u0635\u0627\u0644 (\u0627\u0644\u0645\u0637\u0628\u0639\u0629\u060c \u0645\u062e\u062a\u0628\u0631 \u0627\u0644\u062e\u0631\u0627\u0637\u0629\u2026)"},
gaiJ(){return"\u0632\u0631 \xab\u0625\u0631\u0633\u0627\u0644\xbb \u0641\u064a \u0635\u0641\u062d\u0629 \u0627\u0644\u062d\u0627\u0644\u0629 \u064a\u0631\u0633\u0644 \u0648\u0631\u0642\u0629 \u0627\u0644\u062d\u0627\u0644\u0629 \u0625\u0644\u0649 \u0645\u062d\u0627\u062f\u062b\u0627\u062a \u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645 \u0647\u0630\u0647 \u0628\u0636\u063a\u0637\u0629 \u0648\u0627\u062d\u062f\u0629."},
gaiI(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u062c\u0647\u0627\u062a \u0627\u062a\u0635\u0627\u0644 \u0628\u0639\u062f."},
gLg(){return"\u0625\u0636\u0627\u0641\u0629 \u062c\u0647\u0629 \u0627\u062a\u0635\u0627\u0644"},
gaiD(){return"\u0627\u0644\u0627\u0633\u0645 (\u0645\u062b\u0644\u0627\u064b: \u0627\u0644\u0645\u0637\u0628\u0639\u0629)"},
