ga6Z(){return"\u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633"},
gIK(){return"\u0647\u06d5\u0645\u0648\u0648 \u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646"},
ga6V(){return"\u0646\u0631\u062e (\u0628\u0695 \u0628\u06c6 \u0647\u06d5\u0631 \u06cc\u06d5\u06a9\u06d5\u06cc\u06d5\u06a9\u060c \u06cc\u0627\u0646 %)"},
ga6U(){return"\u0628\u06ce \u0633\u0646\u0648\u0648\u0631 \u0628\u06c6 \u0698\u0645\u0627\u0631\u06d5\u06cc \u06cc\u06d5\u06a9\u06d5\u06a9\u0627\u0646\u06cc \u06a9\u06d5\u06cc\u0633"},
